<?php include '../includes/header.php';$u=user();if(is_admin()){$r=mysqli_query($conn,"SELECT o.*,u.name creator FROM officer_orders o JOIN users u ON u.id=o.created_by ORDER BY o.id DESC");}else{$s=mysqli_prepare($conn,"SELECT o.*,u.name creator FROM officer_orders o JOIN users u ON u.id=o.created_by WHERE o.status='open' AND (o.target_type='all' OR o.target_type=? ) AND (o.target_institution_code='' OR o.target_institution_code=?) ORDER BY o.id DESC");mysqli_stmt_bind_param($s,'ss',$u['institution_type'],$u['institution_code']);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);}?>
<div class="page-head"><div><p class="eyebrow">OFFICIAL ORDERS</p><h1>Orders & Circular Instructions</h1></div><?php if(is_admin()):?><a class="btn primary" href="order_create.php">+ Create Order</a><?php endif;?></div><div class="order-grid"><?php while($x=mysqli_fetch_assoc($r)):?><article class="card order"><div><span class="pill <?=e($x['priority'])?>"><?=e($x['priority'])?></span> <small><?=e($x['created_at'])?></small></div><h3><?=e($x['title'])?></h3><p><?=nl2br(e($x['message']))?></p><small>Target: <?=e($x['target_type'])?><?= $x['target_institution_code'] ? ' · '.e($x['target_institution_code']) : '' ?> · Due: <?=e($x['due_date']?:'—')?></small></article><?php endwhile;?></div><?php include '../includes/footer.php';?>
